import numpy as np, json
from collections import deque
def transform(g, cmap={5:8,7:4,9:3}):
    a=np.array(g); H,W=a.shape; out=a.copy()
    seen=np.zeros_like(a,bool)
    for i in range(H):
        for j in range(W):
            if a[i,j]==2 and not seen[i,j]:
                q=deque([(i,j)]); seen[i,j]=1; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and a[ny,nx]==2 and not seen[ny,nx]:
                                seen[ny,nx]=1; q.append((ny,nx))
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
                h,w=y1-y0+1,x1-x0+1
                if h==w and h>=3 and len(cells)==4*h-4 and h in cmap:
                    for y in range(y0+1,y1):
                        for x in range(x0+1,x1):
                            if out[y,x]==0: out[y,x]=cmap[h]
    return out.tolist()
